import{_ as l,C as t,o as e,c as h,j as i,E as o,a as r,a2 as s}from"./chunks/framework.C21TwvGF.js";const P=JSON.parse(`{"title":"4-dars (Mentor). O‘yin loyihalash va ssenariy: G'oyadan voqealar zanjirigacha","description":"","frontmatter":{"title":"4-dars (Mentor). O‘yin loyihalash va ssenariy: G'oyadan voqealar zanjirigacha","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":2,"link":"/mentor/9-sinf-game/hafta-02/"},"g":4,"title":"O‘yin loyihalash va ssenariy: G'oyadan voqealar zanjirigacha","lead":"Kitobda siz hikoyani o'qiysiz, kinoda uni ko'rasiz, o'yinda esa siz ushbu hikoyaning ichida yashaysiz va uni o'zingiz yaratasiz!","slide":"/slaydlar/9-sinf-game/hafta-02/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-02/dars-1-test.html","student_link":"/9-sinf-game/hafta-02/dars-1","tabs":[{"g":4,"link":"/mentor/9-sinf-game/hafta-02/dars-1","current":true},{"g":5,"link":"/mentor/9-sinf-game/hafta-02/dars-2","current":false},{"g":6,"link":"/mentor/9-sinf-game/hafta-02/dars-3","current":false}],"prev":null,"next":{"g":5,"title":"Photoshop interfeysi va vositalari (1-qism): 2D grafika turlari va interfeys","link":"/mentor/9-sinf-game/hafta-02/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-02/dars-1.md","filePath":"mentor/9-sinf-game/hafta-02/dars-1.md"}`),m={name:"mentor/9-sinf-game/hafta-02/dars-1.md"},y={class:"blk"},d={id:"dars-rejasi",tabindex:"-1"},u={class:"blk"},g={id:"mentor-konspekti",tabindex:"-1"},q={class:"blk"},k={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},b={class:"blk"},v={id:"tezkor-nazorat-savollari",tabindex:"-1"},c={class:"blk"},p={id:"uyga-vazifa",tabindex:"-1"};function f(z,a,_,x,j,T){const n=t("Icon");return e(),h("div",null,[i("div",y,[i("h2",d,[o(n,{name:"file-text"}),a[0]||(a[0]=r(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=s("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga video o&#39;yinlarni loyihalash (Game Conception) bosqichlari, o&#39;yin ssenariysi va uning kino ssenariysidan tub farqi (interaktivlik va o&#39;yinchi tanlovi), o&#39;yin dunyosi (Lore) va qahramonlar arxitekturasi, syujet rivojlanish chizig&#39;i (Narrative Arc) hamda ssenariyni o&#39;yin mexanikasi bilan uzviy bog&#39;lash usullarini o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar o&#39;yin g&#39;oyasini qisqa konsept (High Concept Pitch) shaklida shakllantira oladi; chiziqli (linear) va tarmoqlanuvchi (branching) ssenariylarni ajrata oladi; o&#39;yin qahramonlari, dushmanlari va to&#39;siqlarini syujet bilan bog&#39;lab ssenariy yoza oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan haftani takrorlash (Game Design, Janrlar, UI/UX): 10 daqiqa</li><li>Yangi mavzu: O&#39;yin loyihalash va ssenariy tushunchasi: 20 daqiqa</li><li>Film ssenariysi vs O&#39;yin ssenariysi (Interaktiv hikoya): 20 daqiqa</li><li>Qahramonlar, konflikt va voqealar zanjiri: 20 daqiqa</li><li>Nazorat savollari va amaliy xulosa: 10 daqiqa</li></ul></li></ul><hr>",2))]),i("div",u,[i("h2",g,[o(n,{name:"file-text"}),a[3]||(a[3]=r(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=s('<h3 id="_1-o-yin-loyihalash-game-conception-bosqichlari" tabindex="-1">1. O&#39;yin loyihalash (Game Conception) bosqichlari <a class="header-anchor" href="#_1-o-yin-loyihalash-game-conception-bosqichlari" aria-label="Permalink to &quot;1. O&#39;yin loyihalash (Game Conception) bosqichlari&quot;">​</a></h3><p>O&#39;yin loyihalash — bu shunchaki &quot;o&#39;yin qiziq bo&#39;lsin&quot; deyish emas, balki qat&#39;iy reja asosida ishlab chiqish jarayonidir:</p><ol><li><strong>High Concept (Bosh g&#39;oya):</strong> O&#39;yin nima haqida ekanini 1-2 jumlada tushuntirib berish (masalan: <em>&quot;Yolg&#39;iz qolgan kosmonavt o&#39;z robotini qutqarish uchun vaqt anomaliyalarini yechadi&quot;</em>).</li><li><strong>Target Audience (Maqsadli auditoriya):</strong> O&#39;yin kimlar uchun (yosh, platforma, o&#39;ynash vaqti).</li><li><strong>Core Gameplay Loop (Asosiy zanjir):</strong> O&#39;yinchi har 30–60 soniyada nima ish qiladi?</li><li><strong>Setting (Muhit va davr):</strong> O&#39;yin qayerda va qachon yuz beradi (Kiberpank, O&#39;rta asrlar, Fazoviy stansiya).</li></ol><h3 id="_2-o-yin-ssenariysi-vs-film-ssenariysi" tabindex="-1">2. O&#39;yin ssenariysi vs Film ssenariysi <a class="header-anchor" href="#_2-o-yin-ssenariysi-vs-film-ssenariysi" aria-label="Permalink to &quot;2. O&#39;yin ssenariysi vs Film ssenariysi&quot;">​</a></h3><p>Kino va kitoblarda tomoshabin <strong>passiv kuzatuvchi</strong> bo&#39;ladi: qahramon nima qilsa, uni ko&#39;radi. O&#39;yinda esa o&#39;yinchi <strong>faol ishtirokchi va bosh qahramon</strong> hisoblanadi:</p><ul><li><strong>Interaktivlik:</strong> O&#39;yin ssenariysi o&#39;yinchining qarorlariga moslashishi kerak. Agar o&#39;yinchi chapga bursa, hikoya ham chap tomonga rivojlanishi shart!</li><li><strong>Ssenariy turlari:</strong><ul><li><em>Chiziqli (Linear):</em> Barcha o&#39;yinchilar bir xil syujet bosqichlarini bosib o&#39;tadi (<em>Super Mario</em>, <em>Uncharted</em>).</li><li><em>Tarmoqlanuvchi (Branching):</em> O&#39;yinchining tanloviga qarab turli xil yakunlar (Endings) va voqealar sodir bo&#39;ladi (<em>Detroit: Become Human</em>, <em>The Witcher 3</em>).</li></ul></li></ul><h3 id="_3-qahramonlar-va-konflikt-arxitekturasi" tabindex="-1">3. Qahramonlar va konflikt arxitekturasi <a class="header-anchor" href="#_3-qahramonlar-va-konflikt-arxitekturasi" aria-label="Permalink to &quot;3. Qahramonlar va konflikt arxitekturasi&quot;">​</a></h3><ul><li><strong>Protagonist (Bosh qahramon):</strong> O&#39;yinchi o&#39;zini u bilan identifikatsiya qiladi. Uning aniq maqsadi (Motivation) va kamchiligi (Flaw) bo&#39;lishi kerak.</li><li><strong>Antagonist (Bosh dushman):</strong> Bosh qahramon maqsadiga to&#39;sqinlik qiluvchi shaxs yoki kuch.</li><li><strong>Konflikt turlari:</strong><ul><li><em>Inson tabiatga qarshi:</em> Omon qolish (Survival) o&#39;yinlarida sovuq, ochlik, yirtqichlar bilan kurash;</li><li><em>Inson jamiyatga/dushmanga qarshi:</em> Jangovar va strategik o&#39;yinlar;</li><li><em>Inson o&#39;ziga qarshi:</em> Psixologik jumboqlar va axloqiy tanlovlar.</li></ul></li></ul><h3 id="_4-ssenariyni-o-yin-mexanikasi-bilan-bog-lash-ludonarrative-harmony" tabindex="-1">4. Ssenariyni o&#39;yin mexanikasi bilan bog&#39;lash (Ludonarrative Harmony) <a class="header-anchor" href="#_4-ssenariyni-o-yin-mexanikasi-bilan-bog-lash-ludonarrative-harmony" aria-label="Permalink to &quot;4. Ssenariyni o&#39;yin mexanikasi bilan bog&#39;lash (Ludonarrative Harmony)&quot;">​</a></h3><ul><li>Eng katta xato: ssenariyda qahramon mehribon va muloyim deb ko&#39;rsatilsa-yu, o&#39;yin mexanikasida u hamma narsani sababsiz portlatib yursa, <strong>Ludonarrativ ziddiyat (Ludonarrative Dissonance)</strong> kelib chiqadi.</li><li>Hikoya va o&#39;yin mexanikasi bir-birini to&#39;ldirishi shart: masalan, qahramon yarador bo&#39;lsa, u sekinroq yugurishi va nafas olishi qiyinlashishi lozim.</li></ul><hr>',11))]),i("div",q,[i("h2",k,[o(n,{name:"file-text"}),a[6]||(a[6]=r(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=s('<h3 id="_1-topshiriq-high-concept-pitch-yaratish-oson" tabindex="-1">1-topshiriq. High Concept Pitch yaratish (oson) <a class="header-anchor" href="#_1-topshiriq-high-concept-pitch-yaratish-oson" aria-label="Permalink to &quot;1-topshiriq. High Concept Pitch yaratish (oson)&quot;">​</a></h3><p>O&#39;zingiz o&#39;ylab topgan yangi o&#39;yin uchun 2 jumlalik &quot;High Concept&quot; (Bosh g&#39;oya) yozing: janri, bosh qahramoni va uning bosh maqsadi aks etsin.</p><p><strong>Yechim:</strong><em>&quot;Qadimiy Samarqand rasadxonasida yashovchi yosh munajjim yulduzlar xaritasi yordamida yo&#39;qolgan vaqt darvozasini ochadi va o&#39;tmish xatolarini tuzatish uchun 2D platformer janrida sarguzashtga otlanadi.&quot;</em></p><h3 id="_2-topshiriq-tarmoqlanuvchi-branching-ssenariy-chizish-o-rta" tabindex="-1">2-topshiriq. Tarmoqlanuvchi (Branching) ssenariy chizish (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-tarmoqlanuvchi-branching-ssenariy-chizish-o-rta" aria-label="Permalink to &quot;2-topshiriq. Tarmoqlanuvchi (Branching) ssenariy chizish (o&#39;rta)&quot;">​</a></h3><p>O&#39;yin boshida qahramon yo&#39;l ayrosida turibdi:</p><ul><li>Variant A: Qorong&#39;u g&#39;orga kirish;</li><li>Variant B: Daryo bo&#39;ylab qayiqda suzish. Har ikkala tanlov uchun 2 tadan keyingi oqibat va yakuniy natijani daraxtsimon (sxematik) ko&#39;rinishda tuzing.</li></ul><p><strong>Yechim:</strong></p><ol><li><strong>G&#39;orga kirish:</strong><ul><li>A1: Mash&#39;ala topadi $\\to$ Yashirin xazinani ochadi (G&#39;alaba).</li><li>A2: Qorong&#39;uda qopqonga tushadi $\\to$ Dushmanlar tutib oladi (Mag&#39;lubiyat).</li></ul></li><li><strong>Qayiqda suzish:</strong><ul><li>B1: Tinch qishloqqa yetib boradi $\\to$ Ittifoqchilar orttiradi (Yangi bosqich).</li><li>B2: Sharsharaga duch keladi $\\to$ Qayiq parchalanadi, omon qolish rejimi boshlanadi.</li></ul></li></ol><h3 id="_3-topshiriq-ludonarrativ-uyg-unlikni-ta-minlash-qiyin" tabindex="-1">3-topshiriq. Ludonarrativ uyg&#39;unlikni ta&#39;minlash (qiyin) <a class="header-anchor" href="#_3-topshiriq-ludonarrativ-uyg-unlikni-ta-minlash-qiyin" aria-label="Permalink to &quot;3-topshiriq. Ludonarrativ uyg&#39;unlikni ta&#39;minlash (qiyin)&quot;">​</a></h3><p>Ssenariy bo&#39;yicha bosh qahramon — jismonan zaif, lekin juda aqlli 10 yoshli qizaloq. U tashlandiq robotlar shahrida omon qolishi kerak. Ushbu qahramon uchun 3 ta o&#39;yin mexanikasini loyihalang. U nima uchun qurol bilan hamma robotlarni otib tashlay olmasligi va uning o&#39;rniga nima qilishi kerakligini asoslang.</p><p><strong>Yechim:</strong></p><ol><li><strong>Yashirinish (Stealth) mexanikasi:</strong> U dushmanlar bilan ochiq jangga kirmaydi, qutilar orqasiga yashirinadi va soyalarda harakatlanadi.</li><li><strong>Xakkerlik va buzish (Hacking puzzle):</strong> Qizaloq o&#39;z plansheti orqali xavfsizlik kameralarini o&#39;chiradi yoki robotlarning dasturini o&#39;zgartirib, ularni bir-biriga qarshi qo&#39;yadi.</li><li><strong>Chalg&#39;itish (Distraction):</strong> Tosh yoki temir bo&#39;laklarini uloqtirib shovqin chiqaradi va robotlarni boshqa tomonga yo&#39;naltiradi. <em>Natija:</em> Qahramonning xarakteri va uning o&#39;yindagi imkoniyatlari 100% uyg&#39;unlashadi.</li></ol><hr>',13))]),i("div",b,[i("h2",v,[o(n,{name:"file-text"}),a[9]||(a[9]=r(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=s("<ol><li>O&#39;yin ssenariysining kino ssenariysidan eng asosiy farqi nimada? <ul><li><em>Javob:</em> Interaktivlik va o&#39;yinchining voqealar rivojiga bevosita ta&#39;sir qila olishida.</li></ul></li><li>&quot;Branching narrative&quot; (Tarmoqlanuvchi ssenariy) nimani anglatadi? <ul><li><em>Javob:</em> O&#39;yinchining tanlovlariga qarab turli xil syujet yo&#39;llari va xilma-xil finallar hosil bo&#39;lishini.</li></ul></li><li>Ludonarrativ ziddiyat nima? <ul><li><em>Javob:</em> Hikoyadagi qahramon obrazi bilan o&#39;yinchining o&#39;yinda qilayotgan amallari bir-biriga zid kelib qolishi.</li></ul></li></ol><hr>",2))]),i("div",c,[i("h2",p,[o(n,{name:"house"}),a[12]||(a[12]=r(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("p",null,"O'zingiz o'ylab topgan o'yin uchun qahramon pasporti (Character Sheet) tuzing:",-1)),a[15]||(a[15]=i("ol",null,[i("li",null,"Qahramon ismi va yoshi;"),i("li",null,"Uning bosh maqsadi (Motivation);"),i("li",null,"2 ta kuchli tomoni va 1 ta asosiy kamchiligi (Flaw);"),i("li",null,"O'yin boshlanishiga turtki bo'lgan boshlang'ich hodisa (Inciting Incident).")],-1))])])}const I=l(m,[["render",f]]);export{P as __pageData,I as default};
